def subArrayRanges(nums):
    list_of_subarray=[]
    for i in range(len(nums)):
        for j in range(i,len(nums)+1):
            sub_array=[]
            for k in range(i,j):
                sub_array.append(nums[k])
            if len(sub_array):
                list_of_subarray.append(sub_array)
    sum=0
    for sub_array in list_of_subarray:
        sum+=max(sub_array)-min(sub_array)
    return sum




